package cn.workpanel.module.organization.application;
import cn.workpanel.*;import cn.workpanel.module.organization.infrastructure.HrRepository;import cn.workpanel.module.organization.domain.ContractDates;
import cn.workpanel.shared.application.CurrentActors;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class HrService {
 private final HrRepository repo;private final Db db;private final HrAccess access;private final CurrentActors actors;
 public HrService(HrRepository repo,HrAccess access,CurrentActors actors,Db db){this.repo=repo;this.db=db;this.access=access;this.actors=actors;}
 public Object reminders(Actor request){Actor a=access.require(request,false);return db.rows("SELECT n.id,n.object_id,c.title,c.ends_on,n.created_at FROM notifications n JOIN employee_contracts c ON c.company_id=n.company_id AND c.id=n.object_id WHERE EXISTS(SELECT 1 FROM contract_recipients cr WHERE cr.contract_id=c.id AND cr.user_id=n.recipient_id) AND n.company_id=? AND n.recipient_id=? AND n.type='CONTRACT_EXPIRY' ORDER BY n.sequence DESC LIMIT 100",a.company(),a.id());}
 public Map<String,Object> me(Actor request){Actor a=access.require(request,false);return Map.of("admin",a.admin(),"manage",access.allowed(a.company(),a.id(),true));}
 public List<Map<String,Object>> people(Actor request,int cursor,int limit){Business.page(cursor,limit);return repo.people(access.require(request,false),cursor,limit);}
 @Transactional public void grant(Actor request,String id,Map<String,Object> b){Actor a=actors.fresh(request);a.requireAdmin();Db.fields(b,"access","version");repo.employee(a,id);String level=Db.required(b,"access");if(!Set.of("NONE","READ","MANAGE").contains(level))throw ApiError.bad("INVALID_ACCESS","请选择权限");int v=Db.version(b);
 db.rows("SELECT id FROM outbox_events WHERE company_id=? AND recipient_id=? AND type='CONTRACT_EXPIRY' AND delivered_at IS NULL ORDER BY created_at FOR UPDATE",a.company(),id);
 db.one("SELECT id FROM users WHERE company_id=? AND id=? FOR UPDATE",a.company(),id);
 if(v==0)Db.conflict(db.update("INSERT INTO hr_grants(company_id,user_id,access) VALUES (?,?,?) ON CONFLICT DO NOTHING",a.company(),id,level));else Db.conflict(db.update("UPDATE hr_grants SET access=?,version=version+1 WHERE company_id=? AND user_id=? AND version=?",level,a.company(),id,v));
 if(level.equals("NONE")){db.update("DELETE FROM notifications WHERE company_id=? AND recipient_id=? AND type='CONTRACT_EXPIRY'",a.company(),id);db.update("UPDATE outbox_events SET delivered_at=now() WHERE company_id=? AND recipient_id=? AND type='CONTRACT_EXPIRY' AND delivered_at IS NULL",a.company(),id);}
 db.audit(a,"HR_GRANT_CHANGED",id,Map.of(),Map.of("access",level),"人事授权");}
 @Transactional public void duties(Actor request,String id,Map<String,Object> b){Actor a=access.require(request,true);Db.fields(b,"duties","version");repo.employee(a,id);String text=Db.required(b,"duties");if(text.length()>4000)throw ApiError.bad("INVALID_DUTIES","职责最多4000字");int v=Db.version(b);
 if(v==0)Db.conflict(db.update("INSERT INTO employee_duties(company_id,employee_id,duties) VALUES (?,?,?) ON CONFLICT DO NOTHING",a.company(),id,text));else Db.conflict(db.update("UPDATE employee_duties SET duties=?,version=version+1 WHERE company_id=? AND employee_id=? AND version=?",text,a.company(),id,v));db.audit(a,"EMPLOYEE_DUTIES_UPDATED",id,Map.of(),Map.of("version",v+1),"工作职责");}
 public Map<String,Object> list(Actor request,int cursor,int limit){Actor a=access.require(request,false);Business.page(cursor,limit);return Map.of("items",repo.contracts(a,cursor,limit),"total",db.count("SELECT count(*) FROM employee_contracts WHERE company_id=?",a.company()));}
 public Object history(Actor request,String id){Actor a=access.require(request,false);repo.contract(a,id,false);return db.rows("SELECT version,snapshot,changed_by,changed_at FROM employee_contract_versions WHERE contract_id=? ORDER BY version DESC",id);}
 public Map<String,Object> get(Actor request,String id){Actor a=access.require(request,false);var c=repo.contract(a,id,false);c.put("recipients",db.rows("SELECT user_id FROM contract_recipients WHERE contract_id=? ORDER BY user_id",id).stream().map(r->r.get("user_id")).toList());return c;}
 @Transactional public Map<String,Object> save(Actor request,String id,Map<String,Object> b){Actor a=access.require(request,true);Db.fields(b,"employeeId","title","startsOn","endsOn","attachmentId","recipients","version");int v=Db.version(b);String employee=Db.required(b,"employeeId"),title=Db.required(b,"title"),attachment=Db.required(b,"attachmentId");repo.employee(a,employee);if(title.length()>200)throw ApiError.bad("INVALID_TITLE","标题最多200字");var start=ContractDates.date(b,"startsOn");var end=ContractDates.date(b,"endsOn");if(end.isBefore(start))throw ApiError.bad("INVALID_CONTRACT_DATE","到期日不能早于开始日");
 if(!(b.get("recipients") instanceof List<?> raw)||raw.isEmpty()||raw.size()>50)throw ApiError.bad("INVALID_RECIPIENTS","请选择1至50名授权接收人");var recipients=new TreeSet<String>();for(Object o:(List<?>)b.get("recipients")){if(!(o instanceof String r)||!access.allowed(a.company(),r,false))throw ApiError.bad("INVALID_RECIPIENTS","接收人必须为有效授权人员");recipients.add((String)o);}
 // Lock referenced users before attachments, matching profile's user->attachment lock order.
 var referenced=new TreeSet<String>(recipients);referenced.add(a.id());referenced.add(employee);for(String user:referenced)db.one("SELECT id FROM users WHERE company_id=? AND id=? FOR KEY SHARE",a.company(),user);
 boolean create=id==null;if(create){if(v!=0)throw ApiError.conflict();id=Db.id();}else{var old=repo.contract(a,id,true);if(((Number)old.get("version")).intValue()!=v)throw ApiError.conflict();if(!attachment.equals(old.get("attachment_id")))throw ApiError.bad("CONTRACT_ATTACHMENT_IMMUTABLE","合同附件归档后不可替换，请归档新合同");}
 if(create){db.one("SELECT id FROM attachments WHERE id=? AND company_id=? AND owner_id=? AND storage_state='READY' AND task_id IS NULL AND expires_at IS NULL FOR UPDATE",attachment,a.company(),a.id());if(access.isContract(attachment)||db.count("SELECT count(*) FROM attachment_bindings WHERE attachment_id=?",attachment)>0||db.count("SELECT count(*) FROM users WHERE profile->>'avatarAttachmentId'=?",attachment)>0)throw ApiError.bad("ATTACHMENT_IN_USE","附件已被使用，请重新上传合同专用附件");db.update("INSERT INTO employee_contracts(id,company_id,employee_id,title,starts_on,ends_on,attachment_id,created_by) VALUES (?,?,?,?,?,?,?,?)",id,a.company(),employee,title,java.sql.Date.valueOf(start),java.sql.Date.valueOf(end),attachment,a.id());}
 else Db.conflict(db.update("UPDATE employee_contracts SET employee_id=?,title=?,starts_on=?,ends_on=?,version=version+1 WHERE company_id=? AND id=? AND version=?",employee,title,java.sql.Date.valueOf(start),java.sql.Date.valueOf(end),a.company(),id,v));
 db.update("DELETE FROM contract_recipients WHERE contract_id=?",id);for(String r:recipients)db.update("INSERT INTO contract_recipients(contract_id,user_id) VALUES (?,?)",id,r);
 db.update("INSERT INTO employee_contract_versions(contract_id,version,snapshot,changed_by) VALUES (?,?,?::jsonb,?)",id,v+1,db.write(get(a,id)),a.id());
 db.audit(a,"CONTRACT_ARCHIVED",id,Map.of(),Map.of("version",v+1),"合同归档/修订");return get(a,id);}
}
